  \ifcsundef{blx@bibstringset@string@#2}
    {#1{#3}}
    {\ifcsundef{blx@bibstringsetformat@\csuse{blx@bibstringset@string@#2}}
       {#1{#3}}
       {#1{\csuse{blx@bibstringsetformat@\csuse{blx@bibstringset@string@#2}}
             {#3}}}}}

