       \def\bibcpstring{\blx@imc@biblcstring}%
       \def\bibcplstring{\blx@imc@biblclstring}%
       \def\bibcpsstring{\blx@imc@biblcsstring}}}}
  {\DeclareCaseChangeEquivalent{\bibstring}{%
     \CaseSwitch
       {\blx@imc@bibstring}
       {\blx@imc@bibucstring}
       {\blx@imc@biblcstring}
       {\blx@imc@bibcpstring}}
