  \iffieldundef{#1hour}
    {}
    {\ifboolexpr{test {\iffieldundef{#1endhour}}
                 or
                 test {\iffieldequalstr{#1endhour}{}}}
       {\mktimerange{24h}{#1}}
       {\iffieldsequal{#1hour}{#1endhour}
          % 14:xx:xx 14:xx:xx
          {\iffieldsequal{#1minute}{#1endminute}
             % 14:13:xx 14:13:xx
             {\toggletrue{blx@seconds}%
              \printtext[{#1time}]{%
                \csuse{mkbibtime24h}{#1hour}{#1minute}{#1second}{}%
              \bibtimerangesep
