              \printtext[{#1time}]{\csuse{mkbibtime24h}{#1hour}{#1minute}{}{}%
              \bibtimerangesep
              \csuse{mkbibtime24h}{}{#1endminute}{}{}}}}
          % 14:xx:xx 15:xx:xx
          {\mktimerange{24h}{#1}}}}}

