    {\InputIfFileExists{\blx@auxfile.bbl}
       {\blx@info@noline{... file '\blx@auxfile.bbl' found}%
        \global\toggletrue{blx@bbldone}%
        \blx@generate@bbl@mdfivesum@found{\blx@auxfile.bbl}}
       {\blx@info@noline{... file '\blx@auxfile.bbl' not found}%
