        \blx@appentrydatato\blx@tempb\abx@field@extraalpha
        \blx@appentrydatato\blx@tempb\abx@field@extradate}
       {}%
     \edef\blx@tempb{\endgroup\blx@tempb}%
     \blx@tempb}%
  \blx@adjustyears
